import json
R,C=26,29
pts=[(0,2),(4,3),(4,5),(5,16),(6,18),(7,15),(8,5),(9,16),(10,25),(11,0),(11,16),(12,6),(13,12),(14,20),(14,24),(16,6),(17,14),(17,17),(18,13),(19,14),(19,27),(20,21),(22,22),(22,28),(25,8)]
g=[[2]*C for _ in range(R)]
for r,c in pts:g[r][c]=6
for r in range(R):
 cs=sorted(c for rr,c in pts if rr==r)
 for a,b in zip(cs,cs[1:]):
  if b-a>=3:
   for c in range(a+1,b):g[r][c]=3
for c in range(C):
 rs=sorted(r for r,cc in pts if cc==c)
 for a,b in zip(rs,rs[1:]):
  if b-a>=3:
   for r in range(a+1,b):g[r][c]=3
assert len(g)==26 and all(len(row)==29 for row in g)
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

